import React from 'react';

import { Menu } from '../../../../../navigation/menu/Menu.js';

interface HiddenMenuProps {
  menuItems: React.ReactNode;
}

/* FYI: Do not remove this duplicated menu, as it is entirely necessary for rendering the event listeners from the children. */
export const HiddenMenu = (props: HiddenMenuProps) => {
  return (
    <Menu modal={false} open>
      <Menu.Content
        ref={(node) => {
          if (node) {
            node.style.display = 'none';
          }

          return node;
        }}
      >
        <Menu.Group>{props.menuItems}</Menu.Group>
      </Menu.Content>
    </Menu>
  );
};
